/// Returns an element of `a` corresponding to the q-th quantile (q in [0,100]).
/// Uses a nearest-rank style rule: index = floor(q * (n-1) / 100).
pub fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    debug_assert!(!a.is_empty());
    debug_assert!((0..=100).contains(&q));

    a.sort_unstable();

    let n = a.len();
    if n == 1 {
        return a[0];
    }

    // Widen to avoid overflow and keep index arithmetic safe.
    let q64 = q as i64; // q is guaranteed non-negative here
    let n_minus_1 = (n - 1) as i64;

    let idx = ((q64 * n_minus_1) / 100) as usize;
    a[idx]
}